from __future__ import annotations
from abc_creative_gold_v5_101_200_support import make_spec, register_craft
FACTS={
"ATV":"All-terrain vehicle uses low-pressure tires and straddle seating for off-road travel; it requires trained adult operation, helmet, and approved terrain.",
"Bulldozer":"Tracked construction machine pushes soil or debris with a large front blade; heavy equipment stays inside controlled work zones.",
"Car":"Road motor vehicle mainly designed to carry people; propulsion can be combustion, electric, hybrid, or other systems.",
"Delivery Van":"Enclosed road van carries parcels or goods between stops; loading and parking are part of its service role.",
"Excavator":"Construction machine uses boom, stick, and bucket rotating on an upper structure; it digs rather than simply 'drives'.",
"Fire Engine":"Emergency vehicle carries firefighters, hoses, pumps, ladders, or equipment; other traffic yields according to local law when emergency signals operate.",
"Golf Cart":"Small low-speed vehicle designed mainly for golf courses or controlled properties; road legality and safety rules vary by location.",
"Helicopter":"Rotorcraft gets lift from rotating wings and can hover; it is an aircraft, not a road vehicle.",
"Ice Cream Truck":"Road vending vehicle carries and sells frozen treats; its route/service role differs from ordinary cargo transport.",
"Jeep":"Project label commonly associated with Jeep-brand road/off-road vehicles; exact body and drivetrain depend on the pictured model.",
"Kart":"Small low-slung wheeled vehicle used in controlled karting environments; helmet and track rules are essential.",
"Limousine":"Passenger car with extended or luxury body/service use; it is defined more by passenger service/configuration than speed.",
"Minivan":"Passenger vehicle with boxier body and multiple seating rows, often with sliding side doors.",
"Night Bus":"Bus service operating at night; 'night' describes schedule, not a different propulsion system.",
"Off-road Car":"Vehicle configured for rough terrain with suitable clearance, tires, and drivetrain; off-road does not mean permission to drive anywhere.",
"Plane":"Fixed-wing aircraft produces lift as air flows over wings; it belongs to air transport.",
"Quadcopter":"Aircraft/drone with four rotors; control changes rotor speeds, and flight must follow local safety and airspace rules.",
"Race Car":"Vehicle built for controlled motorsport performance; it belongs on a race circuit, not public-road imitation play.",
"Scooter":"Name can mean kick scooter or motor scooter; this transport mapping requires the pictured type before assigning propulsion.",
"Train":"Rail vehicles coupled or operated to travel on tracks; steel wheels are guided by rails rather than steering like a car.",
"Underground Train":"Rail transit running partly or largely in tunnels; track, signals, and stations guide movement.",
"Vespa":"Vespa is a scooter brand; the mapped vehicle is a motor-scooter type, not a generic word for every scooter.",
"Wagon":"Wheeled carrier can be hand-pulled, animal-drawn, or part of rail terminology; picture context decides the transport type.",
"X-ray Van":"Mobile medical-imaging vehicle can carry X-ray equipment; radiation operation belongs to trained professionals under safety controls.",
"Yard Tractor":"Small tractor or towing tractor used around yards/properties; task and design determine mower, tow, or utility function.",
"Zero-emission Bus":"Bus with no exhaust emissions at the vehicle during operation, commonly battery-electric or fuel-cell; lifecycle emissions can still exist upstream.",
"Ambulance":"Emergency medical vehicle transports patients and clinical equipment; sirens/lights request priority under local rules, not unlimited speed.",
"Bus":"Large road passenger vehicle serving routes, schools, charters, or other services; stops and schedules organize shared travel.",
"Electric Car":"Car propelled by electric motor(s), commonly powered by rechargeable batteries; it has no tailpipe exhaust when fully battery-electric.",
"Forklift":"Industrial truck lifts palletized loads with forks; trained operators use it in controlled workplaces, never as a passenger ride.",
"Garbage Truck":"Waste-collection vehicle loads and transports refuse or recycling; workers and moving mechanisms require clear safety zones.",
"Intercity Bus":"Passenger bus links cities over longer routes; service pattern, not body shape alone, makes it intercity.",
"Jet":"Aircraft propelled by jet engines; jet describes propulsion, not every airplane shape.",
"Kayak":"Small watercraft propelled with a paddle; personal flotation and water conditions matter, and it is not a road machine.",
"Loader":"Construction machine scoops and moves loose material with a front bucket; worksite visibility and exclusion zones are critical.",
"Motorcycle":"Two-wheeled powered road vehicle controlled by handlebars; licensed operation and protective equipment apply.",
"Oil Tanker":"Vehicle or vessel carrying bulk oil; the name can mean tanker truck or tanker ship, so the picture decides mode.",
"Pickup":"Light truck with passenger cab and open cargo bed; cargo must be secured.",
"Road Roller":"Heavy compaction machine presses road base or asphalt with large drums/tires; it is worksite equipment, not ordinary traffic.",
"Utility Truck":"Work vehicle carries tools, crews, or service equipment; exact setup varies by utility task.",
"Van":"Enclosed road vehicle for passengers or cargo; interior configuration defines much of its role.",
"Xpress Bus":"Project label for an express-style bus service; 'Xpress' describes service branding, not a unique vehicle mechanism.",
"Cement Mixer":"Truck-mounted rotating drum keeps concrete agitated during transport; drum rotation is a work function, not the vehicle's propulsion.",
"Dump Truck":"Truck tips or opens its cargo body to unload loose material; unloading needs a level controlled work zone.",
"Hatchback":"Passenger car body style with rear door opening into cargo/passenger space.",
"Narrowboat":"Long narrow inland-waterway boat designed for canals; it is water transport, not a road vehicle.",
"Quad Bike":"Four-wheeled all-terrain vehicle; it requires trained operation, helmet, and terrain-specific safety.",
"Tractor":"Low-speed high-traction machine pulls or powers farm/utility implements; it is a work vehicle more than passenger transport.",
"Wrecker":"Tow/recovery truck lifts or pulls disabled vehicles; roadside recovery needs professional traffic control.",
"Yacht":"Recreational sailing or motor vessel; it belongs to water transport and ranges greatly in size.",
"Zeppelin":"Rigid airship uses a structural framework and lifting gas; it is lighter-than-air aviation, not a road vehicle.",
"Snowplow":"Vehicle or attachment pushes snow from travel surfaces; operators need visibility and people should stay clear of the blade/discharge.",
}
ACTIONS={"ATV":"Point only; no riding mime—name helmet and approved terrain.","Forklift":"Point only; trace forks in the air, never ride-on play.","Race Car":"Point; trace a closed circuit, not a speeding gesture.","Motorcycle":"Point; mime fastening a helmet while standing still.","Quad Bike":"Point; mime helmet strap, no riding stunt.","Road Roller":"Point only; make one slow rolling circle with a finger.","Bulldozer":"Point only; push two flat palms an inch in the air.","Excavator":"Air-trace boom-stick-bucket slowly; no worksite approach.","Loader":"Air-scoop with one hand; keep the machine imaginary.","Cement Mixer":"Trace a drum circle; no climbing gesture.","Dump Truck":"Tilt one flat palm; no standing behind a real truck.","Wrecker":"Air-trace a tow line; never approach roadside recovery.","X-ray Van":"Point only; say professional imaging—no pretend exposure.","Quadcopter":"Air-trace four rotor circles; no real drone flight indoors.","Helicopter":"Point; slowly circle one finger above, no running-to-aircraft mime."}
