GOLD_V5_126_130_SPEC_PATCHES={
"0126":S("0126",authorial_intent="Make Things That Go Parade a transport-mode map: road, rail, air, worksite, and service vehicles are separated, so motion becomes a system of routes rather than one parade lane.",lyric_identity="A child moves markers between road, rail, sky, and worksite cards; the mode must be correct before the vehicle can 'go'.",image_motifs=("car road lane","train rail","helicopter sky","bulldozer work zone","x-ray van service stop"),semantic_arc=("road","rail","air","service/worksite exceptions"),forbidden_generic_language=("things that go parade","everything drives","all on road","go fast"),rhyme_engine="transport-mode-rhyme",chorus_rhyme_engine="road-rail-sky-hook",point_of_view="a child classifying transport modes",chorus_function="repeat road-rail-sky-work",groove_meter="90 BPM route-switch 4/4",round1_grammar="vehicle -> mode -> role/safety",round2_grammar="mode-neutral recall -> target -> safe map gesture",intro_lines=("Car takes road, train takes rail, helicopter takes sky, bulldozer stays in a work zone.","Things that go do not all share one route."),hook_lines=("Road, rail, sky—A-B-C!","Put the vehicle on the route it actually uses."),outro_lines=("Train stays on rails; quadcopter stays in controlled airspace; work machines stay at work.","A to Z ends with every route separated."),style_blueprint="Route-map pop at 90 BPM with guitar, muted drum, bass and marimba. Give road a steady pulse, rail paired clicks kept subtle, air longer phrases, worksite dry low accents—never loud engine SFX.",signature_color="transport-mode",cue_prefix="Mode recall"),
"0127":S("0127",authorial_intent="Make Truck Machine Beat about service-versus-machine role: ambulance, bus, delivery, waste, utility and pickup transport people/goods/services; forklift/loader/roller do work; aircraft/kayak are mode exceptions.",lyric_identity="A child asks whether the object transports, serves, lifts, compacts, or flies/floats before naming it a truck or machine.",image_motifs=("ambulance service","forklift pallet","garbage route","loader bucket","kayak comparison card"),semantic_arc=("public/service","cargo","industrial work","mode exceptions"),forbidden_generic_language=("truck machine beat","all machines trucks","big truck","work fast"),rhyme_engine="service-work-role-rhyme",chorus_rhyme_engine="carry-serve-lift-hook",point_of_view="a child sorting vehicle work roles",chorus_function="repeat carry-serve-work",groove_meter="88 BPM mechanical-but-soft 4/4",round1_grammar="vehicle role plus mechanism/context",round2_grammar="role-neutral recall -> safe gesture",intro_lines=("Ambulance serves patients, bus carries passengers, forklift lifts pallets, road roller compacts a surface.","A machine's job matters more than how big it looks."),hook_lines=("Carry, serve, work—A-B-C!","Name the job before the machine beat."),outro_lines=("Forklift stays in its work zone; kayak stays on water; the bus returns to its route.","A to Z closes with jobs sorted."),style_blueprint="Soft mechanical groove at 88 BPM with woodblock, bass, muted guitar and marimba; rhythm suggests work cycles without alarms, sirens or heavy machinery noise.",signature_color="vehicle-role",cue_prefix="Job recall"),
"0128":S("0128",authorial_intent="Repair Road Vehicle Signs into a road-sign lesson with explicit non-road comparison cards: Jet, Plane, Narrowboat, Yacht, Zeppelin are not road vehicles; signs, lanes and work zones apply only where the mode fits.",lyric_identity="A child places road machines on sign-controlled streets while pulling air/water vehicles to a separate map.",image_motifs=("bus lane","dump-truck work sign","tow recovery cone","yacht water card","zeppelin sky card"),semantic_arc=("ordinary road","heavy road/work","roadside service","air/water exclusions"),forbidden_generic_language=("road vehicles all","jet on road","yacht road","follow sign every vehicle"),rhyme_engine="road-sign-exception-rhyme",chorus_rhyme_engine="road-sign-mode-hook",point_of_view="a child testing whether road rules apply",chorus_function="repeat road-check-mode",groove_meter="86 BPM sign-stop pulse",round1_grammar="vehicle fact plus explicit mode when premise could mislead",round2_grammar="neutral recall -> target -> map/sign gesture",intro_lines=("Bus reads road signs; dump truck enters a work zone; yacht and zeppelin leave the road map entirely.","Before reading the sign, check whether the vehicle is even on a road."),hook_lines=("Road, sign, mode—A-B-C!","A road rule only belongs to road traffic."),outro_lines=("Yacht stays on water, zeppelin stays in air, the wrecker keeps the roadside clear.","A to Z leaves the road map honest."),style_blueprint="Sign-stop 86 BPM pop with piano, muted bass, woodblock and soft guitar. Use clear pauses at mode exceptions; no horns or traffic noise over names.",signature_color="road-rule",cue_prefix="Road check"),
"0129":S("0129",authorial_intent="Make Transport World A-Z about purpose and energy transition: passenger, cargo, emergency, recreation, work, and electric/zero-tailpipe categories overlap without pretending one technology makes every trip sustainable.",lyric_identity="A child compares what is carried, where it travels, and how it is powered; Electric Car and Zero-emission Bus get precise tailpipe language.",image_motifs=("bus passengers","dump cargo","ambulance emergency","electric charging","snowplow service"),semantic_arc=("purpose","route","power","tradeoff/overlap"),forbidden_generic_language=("transport world all clean","electric means no emissions anywhere","every vehicle same job","green vehicle magic"),rhyme_engine="purpose-power-rhyme",chorus_rhyme_engine="carry-route-power-hook",point_of_view="a child comparing transport purpose and propulsion",chorus_function="repeat carry-route-power",groove_meter="90 BPM analytical 6/8",round1_grammar="purpose + mode + power caveat where known",round2_grammar="purpose-neutral retrieval -> target -> safe gesture",intro_lines=("A bus carries many people, a pickup carries a load, an electric car changes the powertrain—not the need for a safe road.","Transport choices have purpose, route, and energy."),hook_lines=("Carry, route, power—A-B-C!","One vehicle can fit more than one category."),outro_lines=("Zero-emission Bus keeps its no-tailpipe claim precise; the world map keeps air, water, and road apart.","A to Z ends with transport as a system of choices."),style_blueprint="Analytical travel-pop at 90 BPM in 6/8 with acoustic guitar, bass, marimba and airy pad. Keep electric lines clean and calm; no futuristic whooshes.",signature_color="purpose-power",cue_prefix="Transport recall"),
"0130":S("0130",authorial_intent="Make Moving Machine March a work-cycle song: arrive, position, dig/load/mix/compact/tow/clear, then leave; motion is subordinated to task and exclusion zones.",lyric_identity="A child watches machines from outside the work boundary and follows sequence rather than celebrating size or noise.",image_motifs=("excavator digging","mixer turning","roller compacting","wrecker tow","snowplow clearing"),semantic_arc=("arrive/position","move material","shape/compact","recover/clear/leave"),forbidden_generic_language=("machine march","big loud machines","come closer","drive the machine"),rhyme_engine="work-cycle-rhyme",chorus_rhyme_engine="arrive-work-clear-hook",point_of_view="a child observing work machines from a safe boundary",chorus_function="repeat arrive-work-clear",groove_meter="84 BPM deliberate work-cycle pulse",round1_grammar="machine -> work function -> exclusion/safety",round2_grammar="work-neutral recall -> target -> air gesture",intro_lines=("Excavator digs, loader carries, mixer turns, roller compacts—and people watch from outside the work zone.","A moving machine moves because a task needs it."),hook_lines=("Arrive, work, clear—A-B-C!","Task before motion, boundary before view."),outro_lines=("Tow line rests, blade lifts, the last work vehicle leaves the marked zone.","A to Z ends when the worksite is clear."),style_blueprint="Deliberate 84 BPM work-cycle groove with low marimba, muted drum, bass and sparse guitar. Avoid engine/siren SFX; sequence is conveyed by rhythm density and pauses.",signature_color="work-cycle",cue_prefix="Work recall"),}
